// Search relevance is educational relevance, never a probability of diagnosis.
let searchMode='general';
const searchStop=new Set('i im ive have having had am is are was were a an the my me been feel feeling feels experiencing experience get getting has it its in on at of for to and with please about information info tell explain why what could can cause causes causing do does this that lately recently really very some sometimes all time when since help understand'.split(' '));
const searchWords={knees:'knee',hurts:'pain',hurt:'pain',hurting:'pain',aching:'pain',ache:'pain',aches:'pain',painful:'pain',anxious:'anxiety',anxity:'anxiety',anxeity:'anxiety',depressed:'depression',tired:'fatigue',tiredness:'fatigue',exhausted:'fatigue',dizzy:'dizziness',dizzyness:'dizziness',dizzines:'dizziness',headaches:'headache',headake:'headache',migrane:'migraine',tummy:'abdominal',belly:'abdominal',stomachache:'abdominal pain',breathless:'shortness of breath',nauseous:'nausea',diabtes:'diabetes'};
const exactNames=new Map();directorySearch.forEach(x=>[x.title,...x.aliases].forEach(n=>{if(!exactNames.has(n))exactNames.set(n,[]);exactNames.get(n).push(x.entry)}));
const searchDocuments=directorySearch.map(x=>({...x,titleWords:new Set(x.title.split(' ')),bodyWords:new Set(x.text.split(' ')),aliasWords:x.aliases.map(a=>new Set(a.split(' ')))}));
normalizeQuery=function(q){let raw=fold(q);if(exactNames.has(raw))return raw;raw=raw.replace(/\b(?:for|since) (?:the past |last )?(?:a|an|one|two|three|four|five|six|seven|several|few|[0-9]+) (?:hours?|days?|weeks?|months?|years?)\b/g,'').replace(/\b(?:left|right|both|mild|persistent|constant)\b/g,'').replace(/\bi m\b/g,'i').replace(/\bi ve\b/g,'i').replace(/\btell me about\b/g,'').replace(/\bwhat (?:is|are)\b/g,'');let words=raw.split(' ').filter(w=>w&&!searchStop.has(w)).map(w=>searchWords[w]||w);let result=[...new Set(words.join(' ').split(' '))].join(' ');result=result.replace(/\bpain (knee|back|neck|shoulder|hip|ankle|wrist|chest|abdominal|joint)\b/g,'$1 pain');return result};
const topicConnections={
 'knee pain':['Knee Injuries and Disorders'],
 anxiety:['Depression','Fatigue','Generalized anxiety disorder'],
 'abdominal pain':['Abdominal Pain'],
 dizziness:['Dizziness and Vertigo'],
 'back pain':['Back Pain'],
 'joint pain':['Joint Disorders'],
 'shortness of breath':['Breathing Problems']
};
function educationalResults(q,{mode=searchMode,filters=true}={}){const n=normalizeQuery(q),terms=n.split(' ').filter(Boolean),related=topicConnections[n]||[],raw=fold(q);if(raw&&!terms.length)return [];
 const ranked=searchDocuments.map(x=>{const e=x.entry,general=e.kinds.includes('health')||e.kinds.includes('encyclopedia'),exact=x.title===n||x.aliases.includes(n),titleAll=terms.length&&terms.every(t=>x.titleWords.has(t)),aliasAll=terms.length&&x.aliasWords.some(a=>terms.every(t=>a.has(t)));let score=0;
 if(!terms.length)score=general?200+(e.hasSummary?20:0):mode==='all'?1:0;
 else if(exact)score=2000+(x.title===n?50:0);
 else if(titleAll||aliasAll)score=1200+(titleAll?50:0)-(x.title.split(' ').length-terms.length)*3;
 else if(related.includes(e.name))score=(n==='knee pain'?1700:1000)-related.indexOf(e.name)*10;
 else if(terms.every(t=>x.bodyWords.has(t))&&(general||mode==='all'))score=(general?150:20)+(e.hasSummary?10:0);
 if(score&&general)score+=200;else if(score&&!exact)score=Math.min(score,500);
 return {e,score};
 });const hasDirect=ranked.some(x=>x.score>=500);return ranked.filter(({e,score})=>score>0&&(mode==='all'||!hasDirect||score>=500)&&(!filters||((!dirState.group||e.groups.includes(dirState.group))&&(!dirState.kind||(dirState.kind==='summary'?e.hasSummary:e.kinds.includes(dirState.kind)))&&(!dirState.letter||(dirState.letter==='#'?/^[0-9]/.test(e.name):e.name[0].toUpperCase()===dirState.letter))))).sort((a,b)=>b.score-a.score||a.e.name.localeCompare(b.e.name)).map(x=>x.e);
}
directoryResults=q=>educationalResults(q);
function setSearchMode(mode){searchMode=mode;dirState.page=0;render()}
searchGo=function(q){dirState={q:'',group:'',kind:'',letter:'',page:0};searchMode='general';dirSearch(q)};
const kneeInfo={title:'Knee pain',url:'https://medlineplus.gov/ency/article/003187.htm',text:'Knee pain is a symptom, not a diagnosis. It can develop after exercise or an injury, or build gradually. Overuse, tendon or ligament injuries, and joint conditions are among the possible explanations. The location, swelling and how the pain began help a clinician assess it.',care:'Contact a clinician if you cannot put weight on the knee, it locks or looks deformed, pain is severe, or you have fever with redness, warmth or swelling. Pain after an accident or injury also needs medical advice.',review:'Source updated by C. Benjamin Ma, MD, Professor and Chief of Sports Medicine and Shoulder Service, UCSF. Source review: November 7, 2024.'};
function kneeOverview(){return `<section class="card readable symptom-overview"><span class="eyebrow">START WITH THE SYMPTOM</span><h2>Knee pain: understand the symptom first</h2><p>${kneeInfo.text}</p><h3>When to contact a clinician</h3><p>${kneeInfo.care}</p><div class="source"><a href="${kneeInfo.url}" target="_blank" rel="noopener">Knee pain · MedlinePlus / A.D.A.M. medical encyclopedia ↗</a><p>${kneeInfo.review}</p><small>Prognos paraphrase of the linked source; not independently clinically reviewed.</small></div></section>`}
function searchLead(q){const n=normalizeQuery(q);if(n==='knee pain')return kneeOverview();if(n==='anxiety')return `<section class="card symptom-overview"><span class="eyebrow">UNDERSTAND THE TOPIC FIRST</span><h2>Anxiety and related experiences</h2><p>Anxiety can involve worry, tension and physical symptoms. Fatigue and sleep difficulties can occur with generalized anxiety disorder, and depression can coexist. These are related reading topics, not conclusions about your symptoms.</p><a class="link" href="https://www.nimh.nih.gov/health/publications/generalized-anxiety-disorder-gad" target="_blank" rel="noopener">Evidence & explanation · NIH National Institute of Mental Health ↗</a><p class="fine">Prognos summary of NIMH patient guidance. A symptom search cannot diagnose an anxiety disorder.</p><div class="chips">${['Anxiety','Depression','Fatigue'].map(name=>{const e=exactNames.get(fold(name))?.[0];return e?`<a class="chip" href="#condition/${e.id}">${name}: read the source summary →</a>`:''}).join('')}</div></section>`;const first=educationalResults(q,{filters:false})[0];if(first?.hasSummary&&(fold(first.name)===n||first.aliases.some(a=>fold(a)===n))){const p=first.excerpt.split(/\n\s*\n/).find(p=>p.length>70)||first.excerpt;return `<section class="card symptom-overview"><span class="eyebrow">START HERE · SOURCE OVERVIEW</span><h2>${esc(first.name)}</h2><p>${esc(p)}</p><a class="link" href="#condition/${first.id}">Read the explanation, evidence & sources →</a>${first.sources.slice(0,1).map(directorySource).join('')}</section>`}return ''}
const searchLibrary=library;
library=function(q=''){let html=searchLibrary(q);const n=normalizeQuery(q);const controls=`<section class="search-intent"><div class="atlas-switch" role="group" aria-label="Search scope"><button aria-pressed="${searchMode==='general'}" onclick="setSearchMode('general')">General health & symptoms<small>Direct topic matches and broad patient information first</small></button><button aria-pressed="${searchMode==='all'}" onclick="setSearchMode('all')">Full medical directory<small>Also search descriptions of rare and genetic conditions</small></button></div>${q?`<p class="fine">Searching for <b>${esc(n||'a more specific symptom or condition')}</b>. ${n!==fold(q)?'Everyday wording has been simplified; edit the search if this missed your meaning. ':''}Results are reading suggestions, not likely diagnoses.</p>`:''}</section>${q?searchLead(q):'<div class="notice">Describe how you feel, such as “I have knee pain” or “I feel anxious.” You can also search a specific disease name, including rare conditions.</div>'}`;html=html.replace('<div class="directory-filters">',controls+'<div class="directory-filters">');return html};
liveDirectorySuggest=function(q){clearTimeout(suggestTimer);suggestTimer=setTimeout(()=>{const box=$('#directory-suggest');if(!box)return;const n=normalizeQuery(q);let hits=n.length>1?educationalResults(q,{filters:false}).slice(0,5).map(e=>e.name):[];if(!hits.length&&n.length>1)hits=searchDocuments.filter(x=>x.title.startsWith(n)).sort((a,b)=>Number(b.entry.kinds.includes('health'))-Number(a.entry.kinds.includes('health'))).slice(0,5).map(x=>x.entry.name);if(!hits.length)hits=didYouMean(n);box.innerHTML=hits.map(name=>`<button class="chip" type="button" data-suggestion="${esc(name)}">${esc(name)}</button>`).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>dirSearch(b.dataset.suggestion))},180)};
const rawSpellingSuggestions=didYouMean;didYouMean=q=>rawSpellingSuggestions(normalizeQuery(q));
const priorSearchArticle=directoryArticle;
directoryArticle=function(id,treatments=false){const html=priorSearchArticle(id,treatments);return !treatments&&dirTab==='overview'&&directoryById.get(id)?.name.toLowerCase()==='knee pain'?html.replace('<div class="stack">','<div class="stack">'+kneeOverview()):html};
const priorSearchAsk=ask;
ask=function(q){if(/appointment|doctor visit|prepare|chest pain|can.t breathe|cannot breathe|suicid|stroke|worst headache|severe pain|overdose/i.test(q))return priorSearchAsk(q);if(!q.trim())return;chat.push({role:'user',html:esc(q)});const hits=educationalResults(q,{mode:'general',filters:false}).slice(0,4);chat.push({role:'assistant',html:`${searchLead(q)}<p>Source-backed reading for “${esc(normalizeQuery(q))}”. These are educational matches, not a personalized assessment.</p>${hits.length?hits.map(e=>`<section class="resource-item"><h3><a href="#condition/${e.id}">${esc(e.name)} →</a></h3>${e.excerpt?`<p>${esc(e.excerpt.slice(0,360))}${e.excerpt.length>360?'…':''}</p>`:''}${e.sources.slice(0,1).map(directorySource).join('')}</section>`).join(''):'<p>No clear topic match. Try the main symptom or a condition name.</p>'}<a href="#library/${encodeURIComponent(q)}">Explore these topics in the library →</a>`});render();$('#messages')?.lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'})};
render();
